#!/bin/bash
# Build the GFDL SCM (siena_201207 public release) with gfortran, strict FP.
# Usage: bash reference/scripts/build_reference.sh [variant]   (variant: strict (default))
set -euo pipefail
REF=$(cd "$(dirname "$0")/.." && pwd)
VARIANT=${1:-strict}
export CONDA_REF=${CONDA_REF:-$HOME/miniconda3/envs/eamxx-ref}
export PATH=$CONDA_REF/bin:$PATH
BUILD=$REF/build/$VARIANT
mkdir -p "$BUILD"
cd "$BUILD"
python3 "$REF/scripts/make_hooks.py"
# path_names relative to src
# Source list: reference/hooks/ (generated by make_hooks.py) > overrides/ > src/
while read -r f; do
  if [ -f "$REF/hooks/$f" ]; then echo "$REF/hooks/$f"
  elif [ -f "$REF/overrides/$f" ]; then echo "$REF/overrides/$f"
  else echo "$REF/src/$f"; fi
done < "$REF/exp/path_names" > path_names
echo "$REF/extra/ref_dump.F90" >> path_names
cppDefs="-Duse_netCDF -Duse_LARGEFILE -DSPMD -DLAND_BND_TRACERS -DSCM -DINTERNAL_FILE_NML ${EXTRA_CPPDEFS:-}"
perl "$REF/bin/mkmf" -t "$REF/bin/mkmf.template.gfortran.$VARIANT" -p scm.x -c "$cppDefs" \
     path_names "$REF/src/shared/include" "$REF/src/shared/mpp/include" > mkmf.log
set +e
make -j${NJOBS:-12} scm.x > make.log 2>&1
status=$?
set -e
grep -E "Error|error:" make.log | head -40 || true
if [ $status -ne 0 ]; then echo "BUILD FAILED (see $BUILD/make.log)"; exit 1; fi
echo "BUILD OK: $BUILD/scm.x"
